      tables: [['Mood in relative clauses', ['Antecedent', 'Mood', 'Example'], [['known, exists', 'indicative', 'Tengo un jefe que me escucha.'], ['unknown, wanted', 'subjunctive', 'Quiero un jefe que me escuche.'], ['doesn’t exist', 'subjunctive', 'No hay nadie que lo sepa.'], ['whatever (lo que)', 'subjunctive', 'Haz lo que quieras.']], [2]]],
      rules: [['Non-defining: que or quien/el cual (not just «que» after commas with people — both OK)', 'Mi tía, que/quien vive en Lima, …'], ['lo que + subjunctive = whatever', 'Come lo que te apetezca.']],
