      practice: [mc('Tengo un amigo que ___ en Sevilla.', ['vive', 'viva'], 0), mc('Necesito un ayudante que ___ inglés.', ['habla', 'hable'], 1), mc('No hay nada que ___ hacer.', ['podemos', 'podamos'], 1), fl('Come lo que ___ (querer, tú).', ['quieras']), mc('With commas → the clause is…', ['defining', 'non-defining'], 1), tr('I’m looking for someone who speaks Chinese.', ['busco a alguien que hable chino', 'estoy buscando a alguien que hable chino'])],
      quiz: [mc('Unknown antecedent →', ['indicative', 'subjunctive'], 1), mc('«No hay nadie que…» takes…', ['indicative', 'subjunctive'], 1), mc('Non-defining clauses use…', ['commas', 'no commas'], 0), mc('Vivo en un piso que ___ terraza.', ['tiene', 'tenga'], 0), mc('«Di lo que quieras» =', ['Say what you want (whatever)', 'Say what you wanted'], 0)]
