      tables: [['Three types', ['Type', 'si-clause', 'Result', 'Example'], [['1 · Real', 'si + present', 'present / future / imperative', 'Si llueve, me quedo en casa.'], ['2 · Unreal present', 'si + imperfect subjunctive', 'conditional', 'Si tuviera dinero, viajaría.'], ['3 · Unreal past', 'si + pluperfect subjunctive', 'conditional perfect', 'Si hubiera estudiado, habría aprobado.']], [3]]],
      rules: [['Never present subjunctive after si', '❌ Si tenga'], ['Never conditional after si', '❌ Si tendría'], ['Order is flexible', 'Viajaría si tuviera dinero.']],
      examples: [['Si tienes hambre, come algo.', 'If you’re hungry, eat something.'], ['Si mañana hace sol, iremos a la playa.', 'If it’s sunny tomorrow, we’ll go to the beach.'], ['Si fuera tú, lo aceptaría.', 'If I were you, I’d accept it.'], ['Si viviera cerca, te visitaría más.', 'If I lived nearby, I’d visit you more.'], ['Si hubieras venido, lo habrías visto.', 'If you had come, you would have seen it.'], ['Si no hubiera llovido, habríamos salido.', 'If it hadn’t rained, we would have gone out.']],
